import{_ as a,c as s,o as t,a5 as i}from"./chunks/framework.CgT1UzWm.js";const m=JSON.parse('{"title":"Custom Parameters Annotation","titleTemplate":"NpgsqlRest","description":"Set custom key-value configuration for PostgreSQL REST API endpoints. Add metadata and custom settings to endpoints.","frontmatter":{"outline":[2,3],"title":"Custom Parameters Annotation","titleTemplate":"NpgsqlRest","description":"Set custom key-value configuration for PostgreSQL REST API endpoints. Add metadata and custom settings to endpoints.","head":[["meta",{"name":"keywords","content":"npgsqlrest custom parameters, endpoint metadata, key value config, custom endpoint settings, api custom config"}],["meta",{"property":"og:title","content":"NpgsqlRest Custom Parameters Annotation"}],["meta",{"property":"og:description","content":"Set custom key-value configuration and metadata for endpoints."}],["meta",{"property":"og:type","content":"article"}],["link",{"rel":"canonical","href":"https://npgsqlrest.github.io/annotations/custom-parameters.html"}],["meta",{"property":"og:url","content":"https://npgsqlrest.github.io/annotations/custom-parameters.html"}],["meta",{"property":"og:image","content":"https://npgsqlrest.github.io/og-image.png"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"NpgsqlRest Custom Parameters Annotation"}],["meta",{"name":"twitter:description","content":"Set custom key-value configuration and metadata for endpoints."}],["meta",{"name":"twitter:image","content":"https://npgsqlrest.github.io/og-image.png"}]]},"headers":[],"relativePath":"annotations/custom-parameters.md","filePath":"annotations/custom-parameters.md","lastUpdated":1794206981000}'),n={name:"annotations/custom-parameters.md"};function o(l,e,r,c,d,p){return t(),s("div",null,e[0]||(e[0]=[i(`<h1 id="custom-parameters" tabindex="-1">Custom Parameters <a class="header-anchor" href="#custom-parameters" aria-label="Permalink to &quot;Custom Parameters&quot;">​</a></h1><p>Set custom key-value configuration for the endpoint.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><details class="code-collapsible" open><summary>code</summary><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>@&lt;key&gt; = &lt;value&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></details><p>The <code>@</code> prefix is optional - both <code>@key = value</code> and <code>key = value</code> work identically. Custom parameters with <code>@</code> prefix are stored without the prefix (e.g., <code>@my_param = value</code> is stored as <code>my_param</code>).</p><div class="tip custom-block"><p class="custom-block-title">Misspelt keys (since 4.0.0)</p><p>Any <code>key = value</code> line is stored, so a misspelt key does nothing. When the line is written with the <code>@</code> prefix and nothing reads that key, NpgsqlRest logs a warning at startup (<code>&quot;@tsclinet_module = users&quot; - nothing reads a custom parameter named tsclinet_module</code>), and <code>npgsqlrest --endpoints</code> lists it under <code>unknownAnnotations</code> and <code>unknownCustomParameters</code>. <code>npgsqlrest --annotations</code> lists every key that is read. A key that your own application reads from <code>CustomParameters</code> is reported as well when written with <code>@</code>: write it without the prefix, or register it with <code>CommentAnnotations.Register(...)</code>.</p></div><p>A comment line that begins with <code>@</code> and is not an annotation at all (<code>@color blue</code>) is ignored: it is not stored, and since 4.0.0 it is no longer published as part of the endpoint&#39;s description by OpenAPI and MCP.</p><h2 id="dynamic-parameter-values" tabindex="-1">Dynamic Parameter Values <a class="header-anchor" href="#dynamic-parameter-values" aria-label="Permalink to &quot;Dynamic Parameter Values&quot;">​</a></h2><p>Some parameters support dynamic values using the <code>{param_name}</code> format, where <code>param_name</code> references a function parameter or an <a href="./parameter-substitution.html#environment-variables">allowlisted environment variable</a> (<code>NpgsqlRest:AvailableEnvVars</code>). Parameter values are resolved at runtime from the actual value passed to the endpoint; environment variables are resolved once at startup, and a parameter with the same name takes precedence. Since 3.21.0 the strict forms work here too: <code>{!name}</code> resolves like <code>{name}</code> for known names, and <code>{!name:fallback}</code> substitutes the inline fallback when an allowlisted variable is unset (with no configured default) or when a parameter value is null — e.g. <code>@file_system_path = {!UPLOAD_ROOT:/var/uploads}</code>. The matching and substitution rules are shared across annotations — see <a href="./parameter-substitution.html">Parameter Value Substitution</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The upload <code>row_command</code> (and <code>csv_row_command</code> / <code>excel_row_command</code>) is SQL text, so placeholders are <strong>never</strong> substituted in it (since 4.0.0) — a request value pasted into SQL would be SQL injection. Pass values through the row command&#39;s <code>$1</code>–<code>$4</code> parameters instead.</p></div><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><details class="code-collapsible" open><summary>sql</summary><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">create</span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;"> function</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> upload_file</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">(_path </span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">text</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">, _file </span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">text</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">)</span></span>
<span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">returns</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> void</span></span>
<span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">language</span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;"> sql</span></span>
<span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">begin</span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;"> atomic</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">;</span></span>
<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">  -- function body</span></span>
<span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">end</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">comment on function upload_file(text, text) is </span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&#39;</span></span>
<span class="line"><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">@upload for file_system</span></span>
<span class="line"><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">@file_system_path = {_path}</span></span>
<span class="line"><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">@file_system_file = {_file}</span></span>
<span class="line"><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&#39;</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div></details><p><strong>Equivalent as a SQL file endpoint</strong> (<code>sql/upload-file.sql</code>):</p><details class="code-collapsible" open><summary>sql</summary><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">/*</span></span>
<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">HTTP POST</span></span>
<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">@upload for file_system</span></span>
<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">@file_system_path = {path}</span></span>
<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">@file_system_file = {file}</span></span>
<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">@define_param path</span></span>
<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">@define_param file</span></span>
<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">*/</span></span>
<span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">select</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div></details><p>The SQL does not reference the two values, so <a href="./define-param.html"><code>@define_param</code></a> declares them as HTTP parameters that only feed the placeholders.</p><p>When called with <code>{&quot;_path&quot;: &quot;/uploads/images&quot;, &quot;_file&quot;: &quot;photo.jpg&quot;}</code>, the file will be saved to <code>/uploads/images/photo.jpg</code>.</p><h2 id="built-in-parameters" tabindex="-1">Built-in Parameters <a class="header-anchor" href="#built-in-parameters" aria-label="Permalink to &quot;Built-in Parameters&quot;">​</a></h2><p>Many annotations support the <code>@key = value</code> syntax. The following sections link to where each parameter group is documented.</p><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><p>These parameters are predefined annotations that also support the <code>key = value</code> syntax:</p><ul><li><a href="./buffer-rows.html">BUFFER_ROWS</a> — <code>buffer_rows</code>, <code>buffer</code></li><li><a href="./raw.html">RAW</a> — <code>raw</code>, <code>raw_mode</code>, <code>raw_results</code></li><li><a href="./separator.html">SEPARATOR</a> — <code>separator</code>, <code>raw_separator</code></li><li><a href="./new-line.html">NEW_LINE</a> — <code>new_line</code>, <code>raw_new_line</code></li><li><a href="./column-names.html">COLUMN_NAMES</a> — <code>columns</code>, <code>names</code>, <code>column_names</code></li><li><a href="./connection.html">CONNECTION</a> — <code>connection</code>, <code>connection_name</code></li><li><a href="./command-timeout.html">COMMAND_TIMEOUT</a> — <code>timeout</code>, <code>command_timeout</code></li><li><a href="./single.html">SINGLE</a> — <code>single</code>, <code>single_record</code>, <code>single_result</code></li><li><a href="./void.html">VOID</a> — <code>void</code>, <code>void_result</code></li><li><a href="./user-context.html">USER_CONTEXT</a> — <code>user_context</code></li><li><a href="./user-parameters.html">USER_PARAMETERS</a> — <code>user_parameters</code>, <code>user_params</code></li><li><a href="./encrypt-decrypt.html">ENCRYPT / DECRYPT</a> — <code>encrypt</code>, <code>decrypt</code> (<code>= true</code> encrypts all text parameters / decrypts all text columns)</li><li><a href="./retry-strategy.html">RETRY_STRATEGY</a> — <code>retry_strategy</code>, <code>retry_strategy_name</code>, <code>retry</code></li><li><a href="./rate-limiter-policy.html">RATE_LIMITER_POLICY</a> — <code>rate_limiter</code>, <code>rate_limiter_policy</code>, <code>rate_limiter_policy_name</code></li><li><a href="./error-code-policy.html">ERROR_CODE_POLICY</a> — <code>error_code_policy</code>, <code>error_code_policy_name</code>, <code>error_code</code></li><li><a href="./basic-auth.html">BASIC_AUTH</a> — <code>basic_auth = &lt;username&gt; &lt;password&gt;</code> adds a user, <code>basic_auth = true</code> only turns it on</li><li><a href="./basic-auth-realm.html">BASIC_AUTH_REALM</a>, <a href="./basic-auth-command.html">BASIC_AUTH_COMMAND</a> — <code>realm</code>, <code>challenge_command</code> (and their aliases)</li></ul><h3 id="upload" tabindex="-1">Upload <a class="header-anchor" href="#upload" aria-label="Permalink to &quot;Upload&quot;">​</a></h3><p>Upload handlers accept custom parameters to control file processing behavior per-endpoint:</p><ul><li><a href="./upload.html#custom-parameters">UPLOAD — Custom Parameters</a></li></ul><h3 id="table-format" tabindex="-1">Table Format <a class="header-anchor" href="#table-format" aria-label="Permalink to &quot;Table Format&quot;">​</a></h3><p>Per-endpoint control of HTML table and Excel spreadsheet rendering:</p><ul><li><a href="./table-format.html">TABLE_FORMAT</a></li></ul><h3 id="server-sent-events" tabindex="-1">Server-Sent Events <a class="header-anchor" href="#server-sent-events" aria-label="Permalink to &quot;Server-Sent Events&quot;">​</a></h3><p>SSE annotations that also support the <code>key = value</code> syntax:</p><ul><li><a href="./sse.html">SSE</a> — <code>sse</code>, <code>sse_path</code>, <code>sse_events_path</code></li><li><code>sse_publish</code>, <code>sse_events_publish</code> — publish this routine&#39;s <code>RAISE</code> messages without giving the endpoint a stream of its own (<code>true</code>, <code>false</code>)</li><li><code>sse_subscribe</code>, <code>sse_events_subscribe</code> — give the endpoint a stream without publishing its own messages (<code>true</code>, <code>false</code>, or a path)</li><li><a href="./sse-events-level.html">SSE_EVENTS_LEVEL</a> — <code>sse_level</code>, <code>sse_events_level</code></li><li><a href="./sse-events-scope.html">SSE_EVENTS_SCOPE</a> — <code>sse_scope</code>, <code>sse_events_scope</code></li></ul><h3 id="typescript-client" tabindex="-1">TypeScript Client <a class="header-anchor" href="#typescript-client" aria-label="Permalink to &quot;TypeScript Client&quot;">​</a></h3><p>Per-endpoint control of generated TypeScript client code:</p><ul><li><a href="./tsclient.html">TSCLIENT</a></li></ul><h3 id="dart-client" tabindex="-1">Dart Client <a class="header-anchor" href="#dart-client" aria-label="Permalink to &quot;Dart Client&quot;">​</a></h3><p>Per-endpoint control of generated Dart client code:</p><ul><li><a href="./dartclient.html">DARTCLIENT</a></li></ul><h2 id="rules-for-keys-and-values" tabindex="-1">Rules for keys and values <a class="header-anchor" href="#rules-for-keys-and-values" aria-label="Permalink to &quot;Rules for keys and values&quot;">​</a></h2><ul><li><strong>Keys are matched in any case</strong> (since 4.0.0): <code>TsClient_Module = users</code> is the same as <code>tsclient_module = users</code>.</li><li><strong>Switches</strong> accept <code>true</code>, <code>on</code>, <code>enabled</code>, <code>1</code> and <code>false</code>, <code>off</code>, <code>disabled</code>, <code>0</code>, in any case (since 4.0.0 for the built-in keys such as <code>raw</code>, <code>single</code>, <code>user_context</code>; the client generators always did).</li><li><strong>A value that is not valid</strong> for a built-in key (<code>raw = maybe</code>, <code>buffer_rows = many</code>, <code>timeout = soon</code>, <code>sse_level = loud</code>, an unknown <code>retry_strategy</code>) is ignored and logged as a warning (since 4.0.0; it used to be ignored in silence).</li><li><strong>Escapes:</strong> <code>\\t</code>, <code>\\n</code> and the like are read as escapes (<code>separator = \\t</code> is a tab). A value that is not a valid escape sequence, such as the Windows path <code>C:\\uploads</code>, is taken as written.</li><li><strong>A key that is one of the routine&#39;s parameters</strong> is not a custom parameter but a <a href="./resolved-parameters.html">resolved parameter</a>, with or without the <code>@</code>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../config/npgsqlrest.html">NpgsqlRest Options configuration</a> - Configure default parameters</li><li><a href="./../config/uploads.html">Upload configuration</a> - Configure upload handlers</li><li><a href="./../config/table-format.html">Table Format Options</a> - Configure table format rendering</li><li><a href="./../config/codegen.html">Code Generation</a> - Configure TypeScript client generation</li><li><a href="./../guide/annotations.html">Comment Annotations Guide</a> - How annotations work</li><li><a href="./../guide/configuration.html">Configuration Guide</a> - How configuration works</li></ul>`,40)]))}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
